278	    private static boolean isBlank(String value) {
279	        return value == null || value.isBlank();
280	    }
281	
282	    /**
283	     * Normalizes a street address into the canonical form stored on and returned for a newly
284	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
285	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
286	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
287	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
288	     * value is what gets persisted, echoed back, and used for every address comparison (household
289	     * duplicate detection and the shared household identifier).
290	     *
291	     * @param rawAddress the address value as supplied by the client
292	     * @return the normalized address (possibly empty, never {@code null})
293	     */
294	    private static String normalizeAddress(String rawAddress) {
295	        if (rawAddress == null) {
296	            return "";
297	        }
298	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
299	        if (collapsed.isEmpty()) {
300	            return "";
301	        }
302	        String[] tokens = collapsed.split(" ");
303	        StringBuilder sb = new StringBuilder(collapsed.length());
304	        for (int i = 0; i < tokens.length; i++) {
305	            String token = tokens[i];
306	            switch (token) {
307	                case "ST" -> token = "STREET";
308	                case "RD" -> token = "ROAD";
309	                case "AVE" -> token = "AVENUE";
310	                default -> { }
311	            }
312	            if (i > 0) {
313	                sb.append(' ');
314	            }
315	            sb.append(token);
316	        }
317	        return sb.toString();
318	    }
319	
320	    /**
321	     * Builds the customer code assigned to a newly created owner. The code is formatted
322	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
323	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
324	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
325	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
326	     *
327	     * @param city the city of the owner being created
328	     * @param lastName the last name of the owner being created
329	     * @return the customer code to assign
330	     */
331	    private String nextCustomerCode(String city, String lastName) {
332	        String city3 = letterPrefix3(city);
333	        String last3 = letterPrefix3(lastName);
334	        String normalizedCity = normalizeIdentity(city);
335	        long sequence = this.clinicService.findAllOwners().stream()
336	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
337	            .count() + 1L;
338	        return String.format("%s-%s-%04d", city3, last3, sequence);
339	    }
340	
341	    /**
342	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
343	     * characters. Values with fewer than three letters yield a shorter prefix.
344	     *
345	     * @param value the source text
346	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
347	     */
348	    private static String letterPrefix3(String value) {
349	        StringBuilder prefix = new StringBuilder(3);
350	        if (value != null) {
351	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
352	                char c = value.charAt(i);
353	                if (Character.isLetter(c)) {
354	                    prefix.append(Character.toUpperCase(c));
355	                }
356	            }
357	        }
358	        return prefix.toString();
359	    }
360	
361	    /**
362	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
363	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
364	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
365	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
366	     * the national number must match the country code: {@code +61} requires 9 national digits and
367	     * {@code +1} requires 10.
368	     *
369	     * @param rawTelephone the telephone value as supplied by the client
370	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
371	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
372	     */
373	    private static String normalizeTelephone(String rawTelephone) {
374	        if (rawTelephone == null) {
375	            throw new InvalidTelephoneException(rawTelephone);
376	        }
377	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
378	        String e164;
379	        if (cleaned.startsWith("+")) {
380	            String digits = cleaned.substring(1);
381	            if (!digits.matches("[0-9]+")) {
382	                throw new InvalidTelephoneException(rawTelephone);
383	            }
384	            e164 = "+" + digits;
385	        } else {
386	            if (!cleaned.matches("[0-9]+")) {
387	                throw new InvalidTelephoneException(rawTelephone);
388	            }
389	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
390	            e164 = "+61" + national;
391	        }
392	        int digitCount = e164.length() - 1;
393	        if (digitCount < 8 || digitCount > 15) {
394	            throw new InvalidTelephoneException(rawTelephone);
395	        }
396	        if (e164.startsWith("+61")) {
397	            if (e164.length() - "+61".length() != 9) {
398	                throw new InvalidTelephoneException(rawTelephone);
399	            }
400	        }
401	        else if (e164.startsWith("+1")) {
402	            if (e164.length() - "+1".length() != 10) {
403	                throw new InvalidTelephoneException(rawTelephone);
404	            }
405	        }
406	        return e164;
407	    }
408	
409	    /**
410	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
411	     * telephones are themselves E.164, so the values are compared directly.
412	     *
413	     * @param e164Telephone the E.164 telephone of the owner being created
414	     * @return {@code true} if another owner already has the same E.164 telephone
415	     */
416	    private boolean isTelephoneInUse(String e164Telephone) {
417	        return this.clinicService.findAllOwners().stream()
418	            .map(Owner::getTelephone)
419	            .filter(existing -> existing != null)
420	            .anyMatch(e164Telephone::equals);
421	    }
422	
423	    /**
424	     * Determines whether any existing owner already uses the given email, compared case-insensitively
425	     * on its lower-cased value. Stored emails are themselves lower-cased, so the supplied value is
426	     * lower-cased and compared directly. A {@code null} or blank email is never considered in use.
427	     *
428	     * @param email the email of the owner being created, as supplied by the client
429	     * @return {@code true} if another owner already has the same lower-cased email
430	     */
431	    private boolean isEmailInUse(String email) {
432	        if (email == null || email.isBlank()) {
433	            return false;
434	        }
435	        String normalizedEmail = email.toLowerCase(java.util.Locale.ROOT);
436	        return this.clinicService.findAllOwners().stream()
437	            .map(Owner::getEmail)
438	            .filter(existing -> existing != null)
439	            .anyMatch(normalizedEmail::equals);
440	    }
441	
442	    /**
443	     * Determines whether any existing owner already shares a household with the owner being created,
444	     * i.e. has both the same last name and the same address. Both fields are compared
445	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
446	     *
447	     * @param lastName the last name of the owner being created
448	     * @param address the address of the owner being created
449	     * @return {@code true} if another owner already has the same last name and address
450	     */
451	    private boolean isHouseholdInUse(String lastName, String address) {
452	        String normalizedLastName = normalizeIdentity(lastName);
453	        String normalizedAddress = normalizeIdentity(address);
454	        return this.clinicService.findAllOwners().stream()
455	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
456	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
457	    }
458	
459	    /**
460	     * Counts how many existing owners already share the given first name and last name with the
461	     * owner being created. Both names are compared case-insensitively (after trimming and
462	     * collapsing runs of whitespace). The count reflects the state before the new owner is
463	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
464	     *
465	     * @param firstName the first name of the owner being created
466	     * @param lastName the last name of the owner being created
467	     * @return the number of existing owners sharing the same first and last name
468	     */
469	    private int namesakeCount(String firstName, String lastName) {
470	        String normalizedFirstName = normalizeIdentity(firstName);
471	        String normalizedLastName = normalizeIdentity(lastName);
472	        return (int) this.clinicService.findAllOwners().stream()
473	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
474	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
475	            .count();
476	    }
477	
478	    /**
479	     * Counts how many members the owner being created belongs to in its household, including
480	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
481	     * the new owner is not yet persisted, so its own membership is added to the existing count.
482	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
483	     * household of one.
484	     *
485	     * @param householdId the shared household identifier assigned to the owner being created, or
486	     *                    {@code null} if the owner does not share a household
487	     * @return the number of household members after this create (at least 1)
488	     */
489	    private int householdSizeAfterCreate(String householdId) {
490	        if (householdId == null) {
491	            return 1;
492	        }
493	        long existing = this.clinicService.findAllOwners().stream()
494	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
495	            .count();
496	        return (int) existing + 1;
497	    }
498	
499	    /**
500	     * The maximum number of owners permitted in a single city. Once a city already contains this
501	     * many owners it is considered full and no further owners may be created there.
502	     */
503	    private static final int CITY_CAPACITY = 50;
504	
505	    /**
506	     * Determines whether the given city has already reached its capacity, i.e. already contains
507	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
508	     * collapsing runs of whitespace to a single space and trimming.
509	     *
510	     * @param city the city of the owner being created
511	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
512	     */
513	    private boolean isCityAtCapacity(String city) {
514	        String normalizedCity = normalizeIdentity(city);
515	        long count = this.clinicService.findAllOwners().stream()
516	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
517	            .count();
518	        return count >= CITY_CAPACITY;
519	    }
520	
521	    /**
522	     * The maximum number of owners that may be created on any single day. Once this many owners
523	     * already carry a {@code registrationDate} of the current day, no further owners may be created
524	     * that day.
525	     */
526	    private static final int DAILY_REGISTRATION_LIMIT = 100;
527	
528	    /**
529	     * Determines whether the daily registration limit has already been reached, i.e. whether
530	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
531	     * their {@code registrationDate}.
532	     *
533	     * @param date the current day
534	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
535	     *         registered on the given date
536	     */
537	    /**
538	     * Rolls a registration date forward onto a business day. A date that already falls on a
539	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
540	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
541	     * everything derived from it (the membership number's year segment, the daily create-limit).
542	     *
543	     * @param date the effective registration date (supplied by the client or defaulted to the
544	     *             server's current date)
545	     * @return the same date if it is a weekday, otherwise the following Monday
546	     */
547	    private static LocalDate toBusinessDay(LocalDate date) {
548	        DayOfWeek dayOfWeek = date.getDayOfWeek();
549	        if (dayOfWeek == DayOfWeek.SATURDAY) {
550	            return date.plusDays(2);
551	        }
552	        if (dayOfWeek == DayOfWeek.SUNDAY) {
553	            return date.plusDays(1);
554	        }
555	        return date;
556	    }
557	
558	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
559	        long count = this.clinicService.findAllOwners().stream()
560	            .filter(existing -> date.equals(existing.getRegistrationDate()))
561	            .count();
562	        return count >= DAILY_REGISTRATION_LIMIT;
563	    }
564	
565	    /**
566	     * The number of owners that may be created on a single day before the bulk-signup warning is
567	     * raised. Once <em>more than</em> this many owners already carry the current business day as
568	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
569	     */
570	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
571	
572	    /**
573	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
574	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
575	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
576	     *
577	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
578	     *         registered on today's business day
579	     */
580	    private boolean isBulkSignupWarning() {
581	        LocalDate today = toBusinessDay(LocalDate.now());
582	        long count = this.clinicService.findAllOwners().stream()
583	            .filter(existing -> today.equals(existing.getRegistrationDate()))
584	            .count();
585	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
586	    }
587	
588	    /**
589	     * Assigns the owner being created to the household identified by the given last name and
590	     * address and returns the household's stable shared identifier. The identifier is derived
591	     * deterministically from the normalized last name and address, so every member of the same
592	     * household resolves to the same value regardless of creation order. Any existing member that
593	     * does not yet carry the identifier is back-filled so all household members share it.
594	     *
595	     * @param lastName the last name of the owner being created
596	     * @param address the address of the owner being created
597	     * @return the stable household identifier shared by all members of the household
598	     */
599	    private String joinHousehold(String lastName, String address) {
600	        String householdId = householdIdFor(lastName, address);
601	        String normalizedLastName = normalizeIdentity(lastName);
602	        String normalizedAddress = normalizeIdentity(address);
603	        for (Owner existing : this.clinicService.findAllOwners()) {
604	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
605	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
606	                && !householdId.equals(existing.getHouseholdId())) {
607	                existing.setHouseholdId(householdId);
608	                this.clinicService.saveOwner(existing);
609	            }
610	        }
611	        return householdId;
612	    }
613	
614	    /**
615	     * Derives the stable household identifier for a given last name and address. The value is the
616	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
617	     * address, so it is stable across calls and identical for every member of the household.
618	     *
619	     * @param lastName the last name of the household
620	     * @param address the address of the household
621	     * @return the stable household identifier
622	     */
623	    private static String householdIdFor(String lastName, String address) {
624	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
625	        try {
626	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
627	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
628	            StringBuilder sb = new StringBuilder(digest.length * 2);
629	            for (byte b : digest) {
630	                sb.append(String.format("%02x", b));
631	            }
632	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
633	        }
634	        catch (java.security.NoSuchAlgorithmException e) {
635	            throw new IllegalStateException("SHA-256 not available", e);
636	        }
637	    }
638	
639	    /**
640	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
641	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
642	     * single space, and the result is lower-cased.
643	     *
644	     * @param value the raw field value
645	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
646	     */
647	    private static String normalizeIdentity(String value) {
648	        if (value == null) {
649	            return "";
650	        }
651	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
652	    }
653	}
